import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

// A naive 3D transposed convolution kernel with support for groups.
// Shapes/arguments:
//   input:  (N, inC, inD, inH, inW)
//   weight: (outC, inC/groups, kD, kH, kW)
//   bias:   (outC) or empty
//   output: (N, outC, outD, outH, outW)
//
// outD, outH, outW are computed as:
//   outD = (inD - 1)*strideD - 2*padD + kD + outPadD
//   outH = (inH - 1)*strideH - 2*padH + kH + outPadH
//   outW = (inW - 1)*strideW - 2*padW + kW + outPadW

__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N,
    int inC,
    int inD,
    int inH,
    int inW,
    int outC,
    int outD,
    int outH,
    int outW,
    int kD,
    int kH,
    int kW,
    int strideD,
    int strideH,
    int strideW,
    int padD,
    int padH,
    int padW,
    int outPadD,
    int outPadH,
    int outPadW,
    int groups,
    bool hasBias)
{
    int total = N * outC * outD * outH * outW;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    // Decompose idx into (n, oc, od, oh, ow)
    int ow = idx % outW;
    int oh = (idx / outW) % outH;
    int od = (idx / (outW * outH)) % outD;
    int oc = (idx / (outW * outH * outD)) % outC;
    int n  = idx / (outW * outH * outD * outC);

    // Figure out which group we are in, if any
    int group_id = oc / (outC / groups); // integer division
    int oc_in_group = oc % (outC / groups);

    float val = 0.0f;
    // Naive accumulation
    // For each kernel element
    for (int kd = 0; kd < kD; kd++) {
        // Compute the corresponding input depth index
        int id_out = od + padD - kd;
        if (id_out % strideD != 0) continue; // must land exactly on a stride
        int id = id_out / strideD;
        if (id < 0 || id >= inD) continue;

        for (int kh = 0; kh < kH; kh++) {
            int ih_out = oh + padH - kh;
            if (ih_out % strideH != 0) continue;
            int ih = ih_out / strideH;
            if (ih < 0 || ih >= inH) continue;

            for (int kw = 0; kw < kW; kw++) {
                int iw_out = ow + padW - kw;
                if (iw_out % strideW != 0) continue;
                int iw = iw_out / strideW;
                if (iw < 0 || iw >= inW) continue;

                // For each input channel in this group
                int inCPerGroup = inC / groups;
                for (int icg = 0; icg < inCPerGroup; icg++) {
                    int ic = group_id * inCPerGroup + icg;
                    float inp_val = input[n * (inC * inD * inH * inW)
                                          + ic * (inD * inH * inW)
                                          + id * (inH * inW)
                                          + ih * inW
                                          + iw];
                    float w_val = weight[oc * (inCPerGroup * kD * kH * kW)
                                         + icg * (kD * kH * kW)
                                         + kd * (kH * kW)
                                         + kh * kW
                                         + kw];
                    val += inp_val * w_val;
                }
            }
        }
    }
    // Add bias if present
    if (hasBias) {
        val += bias[oc];
    }
    // Store
    output[idx] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outPadD, int outPadH, int outPadW,
    int groups)
{
    // Input shape: [N, inC, inD, inH, inW]
    // Weight shape: [outC, inC/groups, kD, kH, kW]
    // Optional bias shape: [outC]
    auto N = input.size(0);
    auto inC = input.size(1);
    auto inD = input.size(2);
    auto inH = input.size(3);
    auto inW = input.size(4);

    auto outC = weight.size(0);
    auto kD   = weight.size(2);
    auto kH   = weight.size(3);
    auto kW   = weight.size(4);

    // Compute output sizes
    int outD = (inD - 1)*strideD - 2*padD + kD + outPadD;
    int outH = (inH - 1)*strideH - 2*padH + kH + outPadH;
    int outW = (inW - 1)*strideW - 2*padW + kW + outPadW;

    // Allocate output
    auto out_options = input.options().dtype(input.dtype());
    auto output = torch::zeros({(long)N, (long)outC, (long)outD, (long)outH, (long)outW}, out_options);

    int total = N * outC * outD * outH * outW;

    // Launch kernel
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    bool hasBias = bias.numel() == outC;
    conv_transpose3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        hasBias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, inC, inD, inH, inW,
        outC, outD, outH, outW,
        kD, kH, kW,
        strideD, strideH, strideW,
        padD, padH, padW,
        outPadD, outPadH, outPadW,
        groups,
        hasBias
    );

    return output;
}
""".strip()

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outPadD, int outPadH, int outPadW,
    int groups
);
""".strip()

# Build the custom CUDA extension
conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    extra_cflags=["-O2"],
    extra_ldflags=["-O2"],
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    A Model that replaces nn.ConvTranspose3d with a custom CUDA transposed convolution operator.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1, 1),
        padding: tuple = (0, 0, 0),
        output_padding: tuple = (0, 0, 0),
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.use_bias = bias

        # Weight shape: [outC, inC/groups, kD, kH, kW]
        kD, kH, kW = kernel_size
        wshape = (out_channels, in_channels // groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.randn(wshape))

        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        strideD, strideH, strideW = self.stride
        padD, padH, padW = self.padding
        outPadD, outPadH, outPadW = self.output_padding
        bias = self.bias if self.use_bias else torch.empty(0, device=x.device, dtype=x.dtype)
        return conv_transpose3d_module.conv_transpose3d_cuda(
            x,
            self.weight,
            bias,
            strideD, strideH, strideW,
            padD, padH, padW,
            outPadD, outPadH, outPadW,
            self.groups
        )
